feed:
	{{ config.title }}
	{{ config.description }}


    {{ config.base_url | safe }}/icon.svg
	Zola
	{{ last_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
	{{ config.base_url | safe }}
	{%- for page in pages[:config.extra.feed_length] %}

		{{ page.title }}
		{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
		{{ (page.updated or page.date) | date(format="%Y-%m-%dT%H:%M:%S%:z") }}

		{{ page.permalink | safe }}
		{{ page.content }}

	{%- endfor %}
